            public TextureHandle src;
        }

        public override void RecordRenderGraph(RenderGraph renderGraph, ContextContainer frameData)
        {
            var resourceData = frameData.Get<UniversalResourceData>();
            if (!resourceData.activeColorTexture.IsValid()) return;

            // 1. descripting temporary texture
            var desc = renderGraph.GetTextureDesc(resourceData.activeColorTexture);
            desc.name = "TempColorBuffer";
            TextureHandle tempTexture = renderGraph.CreateTexture(desc);

            // 2. FIRST PASS: Copy screen tex into temp tex
            using (var builder = renderGraph.AddRasterRenderPass<PassData>("Copy Screen Pass", out var passData))
            {
                passData.src = resourceData.activeColorTexture;
                builder.UseTexture(passData.src, AccessFlags.Read);
                builder.SetRenderAttachment(tempTexture, 0);

                builder.SetRenderFunc((PassData data, RasterGraphContext context) =>
