                    // Simple copy without material
                    Blitter.BlitTexture(context.cmd, data.src, new Vector4(1, 1, 0, 0), 0, false);
                });
            }

            // 3. SECOND PASS: Drawing from temp tex into main one with effect
            using (var builder = renderGraph.AddRasterRenderPass<PassData>("Grayscale Effect Pass", out var passData))
